# Generated by tabcap replay export-python. One case per generated function:
# call it against the replay server with the first recorded sample's values
# and compare with fixtures/index.json (status, JSON keys, constant fields,
# or the body hash for text / binary answers).
from __future__ import annotations

import base64
import hashlib
import json
import re
from pathlib import Path
from typing import Any

import pytest

import client
from client import Session

HERE = Path(__file__).parent
INDEX = json.loads((HERE / "fixtures" / "index.json").read_text("utf-8"))
CASES: list[dict[str, Any]] = INDEX["cases"]
_IDENT = re.compile(r"[A-Za-z_$][A-Za-z0-9_$]*")


def _arg(v: Any) -> Any:
    if isinstance(v, dict) and set(v) == {"$bytes_b64"}:
        return base64.b64decode(v["$bytes_b64"])
    return v


def flatten(value: Any, path: str = "$", out: dict[str, Any] | None = None) -> dict[str, Any]:
    """Path -> leaf, the same paths as tabcap (`$.a[0]`, `$["odd key"]`); empty containers are leaves."""
    out = {} if out is None else out
    if isinstance(value, list):
        if not value:
            out[path] = []
        for i, v in enumerate(value):
            flatten(v, f"{path}[{i}]", out)
    elif isinstance(value, dict):
        if not value:
            out[path] = {}
        for k, v in value.items():
            key = f"{path}.{k}" if _IDENT.fullmatch(k) else f"{path}[{json.dumps(k, ensure_ascii=False)}]"
            flatten(v, key, out)
    else:
        out[path] = value
    return out


@pytest.mark.parametrize("case", CASES, ids=[c["function"] for c in CASES])
def test_replay(case: dict[str, Any], session: Session, base_url: str) -> None:
    fn = getattr(client, case["function"])
    args = {k: _arg(v) for k, v in case["args"].items()}
    if case["todo"]:
        with pytest.raises(NotImplementedError):
            fn(session, base_url=base_url, **args)
        return
    reply = fn(session, base_url=base_url, **args)
    assert reply.status in case["status"], f"{case['request']}: status {reply.status}, recorded {case['status']}"
    body = case["body"]
    if body["kind"] == "json":
        got = reply.response.json()
        if body["keys"] is not None:
            assert isinstance(got, dict)
            keys = set(got)
            assert set(body["keys"]) <= keys, f"missing keys {set(body['keys']) - keys}"
            if body["exactKeys"]:
                assert keys == set(body["keys"])
        flat = flatten(got)
        for path, value in body["constants"]:
            assert path in flat, f"{path} missing"
            assert flat[path] == value, f"{path}: {flat[path]!r} != {value!r}"
    elif body["kind"] in ("text", "binary") and body["sha256"] is not None:
        assert hashlib.sha256(reply.response.content).hexdigest() == body["sha256"]
